package com.taller.portal.config;
import com.taller.portal.model.Role; import com.taller.portal.model.RoleName; import com.taller.portal.model.User; import com.taller.portal.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataInitializer { @Bean CommandLineRunner seed(RoleRepository roles,UserRepository users,PasswordEncoder e){return a->{ for(RoleName r:RoleName.values())roles.findByNombre(r).orElseGet(()->roles.save(new Role(r, switch(r){case DUENO->"Administración total";case MECANICO->"Órdenes de servicio";case CLIENTE->"Consulta de sus vehículos";case SECRETARIA->"Agenda y clientes";case DESARROLLADOR->"Gestión técnica y cuentas";}))); if(users.findByEmail("desarrollador@taller.local").isEmpty()){User u=new User();u.nombre="Desarrollador del sistema";u.email="desarrollador@taller.local";u.celular="0000000000";u.passwordHash=e.encode("DevTaller2026!");u.rol=roles.findByNombre(RoleName.DESARROLLADOR).orElseThrow();u.emailVerificado=true;users.save(u);}};}}
